"git status --short && git branch --show-current",
"rg --files client/application client/products client/shared-state/app-context | head -120",
"rg -n \"client/application|application workspace|composition root|catch-all|Application\" docs/architecture/client-boundaries.md client/application/README.md README.md CONTRIBUTING.md WARP.md 2>/dev/null | head -180",
"sed -n '748,772p' /Users/serro/.codex/memories/MEMORY.md"
]; const r=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,max_output_tokens:5000,workdir:"/Users/serro/Documents/dev/n/nucleus"}))); r.forEach((x,i)=>text(JSON.stringify({cmd:cmds[i],result:x.status==="fulfilled"?x.value.output:String(x.reason)})));

