      url.hostname === "gitlab.com" &&
      pathParts.length === 3 &&
      pathParts[0] === "-" &&
      pathParts[1] === "snippets" &&
      fileName.endsWith(".js")
    ) {
      const snippetId = fileName.slice(0, -3);
      if (!snippetId || !isAsciiDigits(snippetId)) return null;
