  if (tagEnd <= 1 || tagEnd > openTagEnd) return null;

  const tagName = text.slice(1, tagEnd).toLowerCase();
  return {
    tag: text.slice(0, openTagEnd + 1),
    tagName,
    openTagEnd
  };
}

function hasOnlyMatchingCloseTag(
  text: string,
  openTagEnd: number,
  tagName: string,
