    }

    function resolveMessage(action: string, count: number, resource: Resource) {
      let prefix = "";
      const itemsLabel = `${count} ${resource}${count > 1 ? "s" : ""}`;
      switch (action) {
        case "star":
          prefix = "Starred";
          break;
        case "unstar":
          prefix = "Unstarred";
          break;
        case "archive":
          prefix = "Archived";
          break;
        case "unarchive":
          prefix = "Unarchived";
          break;
        case "delete":
          prefix = "Deleted";
          break;
        case "unlink":
          prefix = "Unlinked";
          break;
        case "setDate":
          return `Date changed for ${itemsLabel} successfully`;
        case "moveToToday":
          return `Moved ${itemsLabel} to today`;
      }
