import { Product } from "@nucleum/client/config/product.type";
import { productRegistry } from "@nucleum/schema/product.config";
import { ClientStorageKey } from "@nucleum/persistence/persistence.type";
import { clientStorage } from "@nucleum/persistence/persistence.utils";
import { TIMEZONE_CHANGE_RESOURCE_NAME } from "@datafn/client";

import {
  resolveActiveLegacyLocalDataIdentity,
  readLegacyLocalDataRecoveryDecisions,
  resolveLegacyLocalDataRecoveryDecisionKey,
  resolveLegacySourceDatabaseNames,
  resolveLegacyLocalDataRecoveryDecisionKeyFromParts,
  resolveLegacyIdentityScope,
  resolvePendingLegacyLocalDataRecoveryDecisions
} from "@nucleum/persistence/legacy-backup/recovery-identity";
import {
  listExistingIndexedDatabases,
  resolveLegacyIndexedDbFallbackDescriptors,
  shouldIgnoreDatabase,
  openExistingIndexedDatabase,
  resolveLegacyLocalDataProvider,
  readStoreSummaries,
  readStoreBackups,
  fallbackLegacyDatabaseName
} from "@nucleum/persistence/legacy-backup/indexeddb-reader";
import {
  readSurrealStoreBackups,
  normalizeLegacySurrealIdentities,
  createLegacySurrealClient
} from "@nucleum/persistence/legacy-backup/surreal-reader";
import {
  isImportableLegacyStore,
  collectKnownLegacyResources,
  addLegacyKvRecords,
  normalizeLegacyRecord,
  addLegacyLinkJoinRows,
  convertLegacyTimezoneChangeRecord,
  addResourceRecord,
  resolveLegacyStoreResource,
  resolveRecordId,
  convertLegacyResourceRecord,
  resolveLegacyTargetId,
  addLegacyPointLogSession,
  addLegacyEmbeddedJoinRows,
  schemaResources,
  mapRecordCollectionsToObject,
  normalizeLegacyDatafnResourceIds,
  addJoinRecord,
  normalizeLegacyDatafnJoinIds
} from "@nucleum/persistence/legacy-backup/record-conversion";

export type LegacyLocalDataProvider = "dexie" | "indexeddb" | "surreal";

export type LegacyLocalStoreSummary = {
  name: string;
  count: number;
  error?: string;
};

export type LegacyLocalDatabaseSummary = {
  name: string;
  version: number;
  provider: LegacyLocalDataProvider;
  stores: LegacyLocalStoreSummary[];
};

export type LegacyLocalDataSummary = {
  isSupported: boolean;
  databases: LegacyLocalDatabaseSummary[];
};

export type LegacyLocalDataBackup = {
  schema: "nucleum-legacy-local-data-backup";
  version: 1;
  exportedAt: string;
  product: string;
  databases: LegacyLocalDatabaseBackup[];
};

export type LegacyLocalDatabaseBackup = {
  name: string;
  version: number;
  provider: LegacyLocalDataProvider;
  stores: LegacyLocalStoreBackup[];
};

export type LegacyLocalStoreBackup = {
  name: string;
  keyPath: string | string[] | null;
  autoIncrement: boolean;
  indexes: LegacyLocalIndexBackup[];
  records: LegacyLocalRecordBackup[];
  error?: string;
};

export type LegacyLocalIndexBackup = {
  name: string;
  keyPath: string | string[] | null;
  multiEntry: boolean;
  unique: boolean;
};

export type LegacyLocalRecordBackup = {
  key: unknown;
  value: unknown;
};

export type LegacyLocalDataRecoveryAction =
  | "import_old_data"
  | "download_backup_continue";

export type LegacyLocalDataRecoveryDecision = {
  version: 1;
  product: Product;
  identity: string;
  sourceDatabases: string[];
  action: LegacyLocalDataRecoveryAction;
  decidedAt: string;
  sourceRecordCount: number;
  backupExportedAt?: string;
  importedResourceCount?: number;
  importedJoinCount?: number;
  isCloudUploadPending?: boolean;
};

export type LegacyDatafnImportPayload = {
  version: 1;
  exportedAt: string;
  schema: Array<{ name: string; version: number }>;
  resources: Record<string, Array<Record<string, unknown>>>;
  joins?: Record<string, Array<Record<string, unknown>>>;
  kv?: Record<string, unknown>;
};

export type LegacyLocalDataIdentity = {
  userId?: string;
  dapId?: string;
};

export async function detectLegacyLocalData(
  product: Product
): Promise<LegacyLocalDataSummary> {
  if (typeof indexedDB === "undefined") {
    return { isSupported: false, databases: [] };
  }

  const databases: LegacyLocalDatabaseSummary[] = [];
  const identity = await resolveActiveLegacyLocalDataIdentity();
  const descriptors =
    (await listExistingIndexedDatabases()) ??
    resolveLegacyIndexedDbFallbackDescriptors(product, identity);
  for (const descriptor of descriptors) {
    const name = descriptor.name;
    if (!name || shouldIgnoreDatabase(name)) continue;
    const database = await openExistingIndexedDatabase(name).catch(() => null);
