export function resolveUpsertQuery(resource: Resource, record: any) {
  let copy = { ...record };
  let id = copy.id;
  if (id && typeof id === "string" && !id.includes(":")) {
    id = `${resource}:${id}`;
  } else if (typeof id === "object" && id.id) {
