  token: string;
  region: string;
}) {
  await destroyNucleumDatafn();
  const remoteUrl = `${resolveAccountBaseUrl(input.region).replace(/\/$/, "")}/datafn`;
  await datafn.switchContext({
    clientId: `public-link-${crypto.randomUUID()}`,
    namespace: "public-link",
