for name in ("tsconfig.json", "client/tsconfig.json"):
    path = Path(name)
    before = path.read_text()
    after = before.replace("@nucleum/application", "@nucleum/composition")
    if name == "tsconfig.json":
        after = after.replace("./client/application", "./client/composition")
    else:
        after = after.replace("./application", "./composition")
    path.write_text(after)
    print(name)
`;
