import { get, writable } from "svelte/store";
import { AppSkin } from "@21n/theme/appearance.type";
import { type IAppStore } from "@nucleum/shared-state/app-context/app-store.type";
import type { DragAndDrop } from "@21n/ui/actions/draganddrop.type";
import { DragStatus } from "@21n/ui/actions/dragstatus.enum";
import blankJson from "@nucleum/client/config/blank.json";
import colorSchemes from "@21n/theme/colorschemes.json";
import { Resource } from "@nucleum/datafn/resource.enum";
import { shuffleEmojis } from "@21n/ui/elements/avatarPicker/avatars";
import { type IAction } from "@nucleum/client/config/action.type";

import { dispatchCustomEvent } from "@21n/shared-utils/dom-events";
import { persistLocally } from "@nucleum/persistence/legacy-local-storage";

import { InteractionMode } from "@21n/ui/elements/keyboard/interaction-mode.type";
import { Action } from "@nucleum/client/config/action.enum";
import { GlobalEvent } from "@nucleum/shared-state/events/event.enum";

import { Product } from "@nucleum/client/config/product.type";
import { syncElementDebugMode } from "@21n/ui/environment/element-environment.store";

export const currentTime = writable<Date>(new Date());
export const appLoadingState = writable<{
  isBaseLoaded: boolean;
  isLocalLoaded: boolean;
}>({ isBaseLoaded: false, isLocalLoaded: false });
export const leftThresholdCrossedStore = writable("");
export const isTouchDevice = writable(false);

export const appStoreShuffleEmojis = writable(shuffleEmojis);
export const intercomId = import.meta.env?.VITE_INTERCOM_ID ?? "t4qp4qlr";
export const selectedTimePeriod = writable<Date>(new Date());

/**
 * Paths that are excluded to redirection checks like login
 */
export const excludedPathsForRedirectionCheck = [
  "expired",
  "signup",
  "login",
  "404",
  "onboarding",
  "error",
  "welcome",
  "play",
  Action.EXTENSTION_LOGIN,
  "oauth"
];

let blankDetails: any = blankJson.find(
  (subatom: any) => subatom.url == "blank.coop"
);
export const blank = writable(blankDetails);

export const dragAndDropStore = createDragAndDropStore();
const dndPageOwners = new Set<symbol>();

/**
 * Keeps global drag and paste handlers suspended while an owning surface is mounted.
 */
export function acquireDnDPage() {
  const owner = Symbol("dnd-page-owner");
  dndPageOwners.add(owner);
  syncDnDPageState();
  let isReleased = false;
  return () => {
    if (isReleased) return;
    isReleased = true;
    dndPageOwners.delete(owner);
    syncDnDPageState();
  };
}

function syncDnDPageState() {
  appStore.update((state) => ({
    ...state,
    isDnDPageActive: dndPageOwners.size > 0
  }));
}

function createDragAndDropStore() {
  const { subscribe, set, update } = writable<DragAndDrop>({
    dragItem: {},
    dropItem: {},
    dragEnterItem: {},
    dragLeaveItem: {},
    dragStatus: DragStatus.NONE,
    dragId: "",
    dragEnterId: "",
    dropId: "",
    forwardDrop: false
  });

  return {
    subscribe,
    set,
    update,
    reset: () => {
      set({
        dragItem: {},
        dropItem: {},
        dragEnterItem: {},
        dragLeaveItem: {},
        dragStatus: DragStatus.NONE,
        dragId: "",
        dragEnterId: "",
        dropId: "",
        forwardDrop: false
      });
    }
  };
}

const tempColorSchemes = [
  "scheme1",
  "scheme2",
  "scheme3",
  "scheme4",
  "scheme5",
  "scheme6",
  "scheme7",
  "scheme8",
  "scheme9",
  "scheme10",
  "scheme11"
    }
  });

  function refreshUIStateDerived() {
    const interactionMode = uiState.getState(Action.MODE_OF_INTERACTION, {
      scope: UIStateScope.PRODUCT
    });
    $appStore.interactionMode = interactionMode;
  }

  async function startApplication(options?: {
    isOfflinabilityEnabled?: boolean;
  }) {
    if (isStartupCompleted) return;
    const runtime = await initializeDatabase(options);
    if (runtime) {
      try {
        await completeApplicationStartup();
      } catch (startupError) {
        error = "Unable to initialize local data. Please try again later.";
        logger.error({ at: "startApplication", error: startupError });
      }
    }
  }

  async function completeApplicationStartup() {
    if (isStartupCompleted) return;
    await Promise.all([
      initializeUserConfig(),
      recentsStore.refresh(
        resolveProductResources($appStore.product, "search") ?? []
      )
    ]);
    $appLoadingState.isBaseLoaded = true;
    isStartupCompleted = true;
    if (typeof onReady === "function") {
      await onReady();
    }
    if ($context.isEmbed && $context.isSheet) {
      $appLoadingState.isLocalLoaded = true;
    }

