        new CustomEvent("errorLog", {
          detail: {
            error,
            message
          }
        })
      );
    }
  }
  warn(message: unknown) {
    this._log(message, LogType.WARN);
  }
  debug(message: unknown) {
    this._console(message, LogType.DEBUG);
  }

