  offline: {
    action: "offline",
    type: ActionType.PAGE,
    isMeta: true,
    component: Offline
  },
  web: {
    action: "web",
    label: "Open web app",
    icon: "link",
    isMeta: true,
    type: ActionType.LINK
  },
