      title: "Appearance Settings",
      layout: {
        size: Size.lg
      }
    }
  },
  {
    action: "appMenu",
    label: "App Menu",
    icon: "list",
    isInactive: true,
    component: AppMenuSettings
  },
  {
    action: Action.SHORTCUTS,
    label: "Keyboard shortcuts",
    icon: "keyboard",
    component: ShortcutSettings,
    hideContext: [Embed.HANDSET]
  },
  {
    action: Action.DATETIME_SETTINGS,
    cmdLabel: "Date & Time Settings",
    label: "Date & Time",
    icon: "calendar-blank",
    component: DateTimeSettings
  },
  {
    action: Action.ACCESSIBILITY,
    get cmdLabel() {
      return this.modalParams?.title;
    },
    label: "Accessibility",
    icon: "person-simple",
    component: AccessibilitySettings,
    modalParams: {
      title: "Accessibility Settings"
    }
  },
  {
    action: "share",
    label: "Refer a friend",
    icon: "share",
    component: ShareToFriends
  },
  {
    action: "about",
    label: "About us",
    icon: "info",
    component: AboutSettings
  },
  {
    action: "sync",
    label: "Sync",
    icon: "sync",
    component: SyncSettings,
    modalParams: {
      title: "Sync Settings"
    },
    hideContext: [UserDataMode.LOCAL]
  }
];

