      return n;
    });
  },
  loadAppData: (data: any, params?: { isDefaultData: boolean }) => {
    update((n: IAppStore) => {
      const env = n.env;
      if (data.env && data.env[env]) {
        n.appData = { ...data, ...data.env[env] };
      } else {
