  element: Element | null,
  selector: string
): Element | null {
  if (!element) return null;

  if (element.matches && element.matches(selector)) {
    return element;
  }
  let currentElement: Element | ParentNode | ShadowRoot | null = element;
  while (currentElement) {
    if (currentElement instanceof ShadowRoot) {
      currentElement = currentElement.host;
    } else {
      currentElement = currentElement.parentNode;
    }
    if (!currentElement || currentElement === document) {
      return null;
    }
    if (currentElement instanceof Element && currentElement.matches(selector)) {
      return currentElement;
    }
  }
  return null;
}

export function resolveParentNLevel(
  n: number,
  element: Element
): Element | null {
  const root = Array.from({ length: n }).reduce<Element | null>(
    (current) => current?.parentElement ?? null,
    element
  );
  return root;
}

export function resolveOgData(doc?: Document) {
  doc = doc ?? document;
  const ogTitle = (
    doc.querySelector("meta[property='og:title']") as HTMLMetaElement
  )?.content;
  const ogImage = (
    doc.querySelector("meta[property='og:image']") as HTMLMetaElement
  )?.content;
  const ogDescription = (
    doc.querySelector("meta[property='og:description']") as HTMLMetaElement
  )?.content;
  const ogUrl = (
