export type Product =
  (typeof BaseProduct)[keyof typeof BaseProduct] | NextProduct;

export const OverviewPanel = {
  ...BaseOverviewPanel,
  ...NextOverviewPanel
} as const;
export type OverviewPanel =
  | (typeof BaseOverviewPanel)[keyof typeof BaseOverviewPanel]
  | NextOverviewPanel;

